void main() {
  test('curated four-byte sequences decode', () {
    expect(Gbk.decode([0x95, 0x32, 0x82, 0x36]), '\u{20000}');
    expect(Gbk.decode([0x98, 0x35, 0xf7, 0x38]), '\u{2a700}');
    expect(Gbk.decode([0x94, 0x39, 0xfc, 0x36]), '\u{1f600}');
    // 一 keeps its two-byte GBK form; four-byte handling never shadows it.
    expect(Gbk.decode([0xd2, 0xbb]), '一');
  });

  test('four-byte decoding matches the gb18030 reference on 173 vectors',
      () {
    final replacement = String.fromCharCode(0xfffd);
    for (final (hex, cp) in _vectors) {
      final bytes = [
        for (var i = 0; i < hex.length; i += 2)
          int.parse(hex.substring(i, i + 2), radix: 16),
      ];
      final expected =
          cp == 0 ? replacement : String.fromCharCode(cp);
      expect(Gbk.decode(bytes), expected, reason: 'bytes $hex');
    }
  });

  test('shaped but truncated four-byte tails degrade without re-parsing',
      () {
    final replacement = String.fromCharCode(0xfffd);
    // Lead + 0x3x announce a four-byte shape; every trailing byte is then
    // consumed even when missing or out of range.
    expect(Gbk.decode([0x95, 0x32]), replacement);
    expect(Gbk.decode([0x95, 0x32, 0x81]), replacement);
    expect(Gbk.decode([0x95, 0x32, 0x40, 0x30]), replacement);
    expect(Gbk.decode([0x95, 0x32, 0x82, 0x36, 0x41]), '\u{20000}A');
  });

  test('encoding stays GBK-conservative', () {
    // Four-byte-only characters (emoji, CJK ext) remain unencodable so the
    // login/review guards keep telling users the server speaks GBK.
    expect(Gbk.canEncode('\u{1f600}'), isFalse);
    expect(Gbk.canEncode('\u{20000}'), isFalse);
    expect(Gbk.tryEncode('\u{20000}'), isNull);
    expect(Gbk.canEncode('中文'), isTrue);
  });

  test('mixed GBK and four-byte content decodes in one pass', () {
    // "第1卷\u{20000}" as GBK bytes + a four-byte ext-B char.
    final bytes = <int>[
      0xb5, 0xda, 0x31, 0xbe, 0xed, // 第1卷
      0x95, 0x32, 0x82, 0x36, // \u{20000}
      0xc7, 0xe1, // 轻
    ];
    expect(Gbk.decode(bytes), '第1卷\u{20000}轻');
  });
}
